const data  = $('Webhook').first().json.body || {};      // la MISE A JOUR
const fiche = $('Charger fiche').first().json || {};     // la FICHE

const chatId = data.message?.chat?.id ||
               data.edited_message?.chat?.id || '';
const texte = data.message?.text ||
              data.message?.caption ||
              data.edited_message?.text ||
              'Message non textuel';
const prenom = data.message?.from?.first_name ||
               'Client';

return [{ json: {
  canal: 'telegram',
  destinataire: String(chatId),
  texte: texte,
  prenom: prenom,

  // Meme greffe que le routeur WhatsApp : le Cerveau ne connait le marchand
  // que par ce qu'on lui passe.
  slug:              fiche.slug || String($('Webhook').first().json.params?.slug || ''),
  boutique_id:       fiche.id || '',
  nom_boutique:      fiche.nom || '',
  // Le metier de la boutique : l'assistante y accorde son vocabulaire, pour
  // ne pas souhaiter bon appetit au client d'une boutique de vetements.
  secteur:           fiche.categorie || '',
  sheet_commandes:   fiche.sheet_commandes || '',
  sheet_menu:        fiche.sheet_menu || '',
  sheet_notes:       fiche.sheet_notes || '',
  groupe_livreurs:   fiche.groupe_livreurs || '',
  telegram_marchand: fiche.telegram_marchand || '',
  whatsapp_marchand: fiche.telephone || '',
  sheet_document_id: fiche.sheet_document_id || '',
}}];

