// Le bouton porte « frais_<montant>_<reference> », ou « frais_autre_<reference> »
// quand le livreur veut saisir un montant qui n'est pas propose.
// La reference peut contenir des tirets bas, comme les callbacks livreur : on
// rejoint donc tout ce qui suit plutot que de prendre parts[2] seul.
const cq = $('Webhook').first().json.body?.callback_query || {};
const data = String(cq.data || '');
const parts = data.split('_');

const brut = String(parts[1] ?? '');
const reference = parts.slice(2).join('_');
const autre = brut === 'autre';
const montant = autre ? null : Number(brut);

// MESSAGE SANS DEUX-POINTS NI RETOUR A LA LIGNE. n8n scinde le texte d'une
// Error sur ces caracteres, et l'alerte n'en recevrait qu'un fragment.
if (!reference || (!autre && !Number.isFinite(montant))) {
  throw new Error(`Frais illisibles dans le bouton livreur — ${data}`);
}

return [{ json: {
  autre,
  montant,
  reference,
  livreur: String(cq.from?.first_name || cq.from?.username || 'Un livreur'),
  groupe: String(cq.message?.chat?.id ?? ''),
} }];

const msg = $('Webhook').first().json.body?.message || {};
const montant = Number(String(msg.text ?? '').trim());
const cite = String(msg.reply_to_message?.text ?? '');

// La reference a ete ecrite par « Demander le montant libre ». L'aiguilleur a
// deja verifie sa presence, donc ce garde-fou ne devrait jamais lever — il est
// la pour que le jour ou le gabarit du message change, la panne se NOMME au
// lieu d'enregistrer un montant sur une commande au hasard.
const m = cite.match(/Commande\s+(\S+)/);
if (!m || !Number.isFinite(montant)) {
  throw new Error(`Montant libre inexploitable — reponse ignoree pour eviter d ecrire sur la mauvaise commande`);
}

return [{ json: {
  autre: false,
  montant,
  reference: m[1],
  livreur: String(msg.from?.first_name || msg.from?.username || 'Un livreur'),
  groupe: String(msg.chat?.id ?? ''),
} }];

